import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart, faTrash } from '@fortawesome/free-solid-svg-icons';
import { FaEye, FaEyeSlash } from 'react-icons/fa';
import './ZapatosCard.css';
import { useSelector } from 'react-redux';

import { addToCart, removeFromCart } from '../../../Carrito/Carrito_Localstorang/CaritoLocalstorang';

const ZapatosCard = ({
  id,
  marca,
  costo,
  color,
  modelo,
  calidad,
  descripcion,
  url,
  talla,
  activo,
}) => {
  const User = useSelector((state) => state.USER);
  const [addedToCart, setAddedToCart] = useState(false);

  const handleActivar = () => {
    alert('Activar');
  };

  const handleOcultar = () => {
    alert('Ocultar');
  };

  const handleAddToCart = () => {
    const item = {
      id,
      marca,
      costo,
      color,
      modelo,
      calidad,
      descripcion,
      url,
      talla,
      quantity: 1 // Ajusta la cantidad según tu necesidad
    };
    addToCart(item);
    setAddedToCart(true); // Cambia el estado para mostrar el botón de eliminar
    alert('Producto agregado al carrito');
  };

  const handleRemoveFromCart = () => {
    removeFromCart(id); // Implementa la función para eliminar del carrito
    setAddedToCart(false); // Cambia el estado para mostrar el botón de agregar nuevamente
    alert('Producto eliminado del carrito');
  };

  return (
    <div className="zapatos-card" title={id}>
      <img src={url} alt="Zapato" className="zapatos-image" />
      <div className="zapatos-info">
        <div className="titulo-zapato">
          <p className="black-text">Marca: </p> {marca}
        </div>
        <div className="zapatos-price">
          <div className="parrafo-flex">
            <p className="black-text">Calidad:</p> {calidad}{' '}
            <p className="black-text"> Categoria:</p> {modelo}
          </div>
          <div className="parrafo-flex">
            <p className="black-text">Tallas:</p> {talla}{' '}
            <p className="black-text"> Color:</p> {color}
          </div>
          <div className="parrafo-flex">
            <p className="black-text">Costo:</p> ${costo}
          </div>
        </div>
        {User.state === 'true' ? (
          activo === 'true' ? (
            <>
              <button className="zapatos-btn-Activar" onClick={() => handleOcultar(id)}>
                <FaEye className="icon" /> Activo
              </button>
              <button className="zapatos-btn-Ocultar" onClick={() => handleActivar(id)}>
                <FaEyeSlash className="icon" /> Oculto
              </button>
            </>
          ) : (
            <>
              {addedToCart ? (
                <button className="zapatos-btn-Eliminar" onClick={() => handleRemoveFromCart()}>
                  <FontAwesomeIcon icon={faTrash} className="icon" /> Eliminar del carrito
                </button>
              ) : (
                <button className="zapatos-btn" onClick={() => handleAddToCart()}>
                  <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
                  Agregar al carrito
                </button>
              )}
            </>
          )
        ) : (
          <button className="zapatos-btn" onClick={() => handleAddToCart()}>
            <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
            Agregar al carrito
          </button>
        )}
      </div>
    </div>
  );
};

export default ZapatosCard;
